import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Placeholder from 'flarum/common/components/Placeholder';
import extractText from 'flarum/common/utils/extractText';
import { api } from '../api';
import { t, date, number, cover, avatar } from '../util';
import ShowModal from './ShowModal';

/** Every show, the most recently updated first. */
export default class PodcastsPage extends Page {
  oninit(vnode) {
    super.oninit(vnode);
    this.bodyClass = 'App--index';
    this.shows = null;
    this.load();
  }
  load() {
    return api.get('shows').then(r => {
      this.shows = r.shows;
      this.canCreate = r.canCreate;
      m.redraw();
    });
  }
  view() {
    app.setTitle(extractText(t('index.title')));
    app.setTitleCount(0);
    return m(PageStructure, {
      className: "IndexPage EarshotPage",
      hero: () => this.hero(),
      sidebar: () => m(IndexSidebar, null)
    }, this.content());
  }
  hero() {
    return m("header", {
      className: "Hero EarshotHero EarshotHero--index"
    }, m("div", {
      className: "EarshotHero-backdrop"
    }), m("div", {
      className: "container EarshotHero-index"
    }, m("div", null, m("h1", {
      className: "DiscussionHero-title"
    }, t('index.title')), m("p", {
      className: "EarshotHero-tagline"
    }, t('index.subtitle'))), this.canCreate ? m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-plus",
      onclick: () => app.modal.show(ShowModal, {
        onsave: show => m.route.set(app.route('earshot.show', {
          slug: show.slug
        }))
      })
    }, t('index.new_show')) : null));
  }
  content() {
    if (!this.shows) return m(LoadingIndicator, null);
    if (!this.shows.length) return m(Placeholder, {
      text: t('index.empty')
    });
    return m("ul", {
      className: "EarshotShows"
    }, this.shows.map(show => m("li", {
      key: show.id
    }, m(Link, {
      className: "EarshotShowCard",
      href: app.route('earshot.show', {
        slug: show.slug
      }),
      style: {
        '--earshot-accent': show.color || undefined
      }
    }, cover(show, 'EarshotShowCard-cover EarshotCover', true), m("div", {
      className: "EarshotShowCard-body"
    }, m("h2", {
      className: "EarshotShowCard-title"
    }, show.title), show.tagline ? m("p", {
      className: "EarshotShowCard-tagline"
    }, show.tagline) : null, m("div", {
      className: "EarshotShowCard-meta"
    }, m("span", {
      className: "EarshotShowCard-hosts"
    }, show.hosts.slice(0, 3).map(u => avatar(u, 'Avatar--mini'))), [t('hero.episodes', {
      count: show.episodeCount
    }), show.lastEpisodeAt ? t('index.latest', {
      date: date(show.lastEpisodeAt)
    }) : null].filter(Boolean).map(part => m("span", null, part))))))));
  }
}
flarum.reg.add('ernestdefoe-earshot', 'forum/components/PodcastsPage', PodcastsPage);